package vn.thiendao.automacro;
import android.accessibilityservice.*;import android.view.*;import android.view.accessibility.*;import android.graphics.*;import android.os.*;import android.widget.*;import org.json.*;
public class Macro extends AccessibilityService {
 static Macro instance; WindowManager wm; LinearLayout bar; View overlay; TextView status; Handler h=new Handler(Looper.getMainLooper()); JSONArray steps=new JSONArray(); String name; int loops,index,round,token; float speed; boolean recording,running,paused; long last,down,delay; JSONArray points; 
 public void onServiceConnected(){instance=this;wm=(WindowManager)getSystemService(WINDOW_SERVICE);}
 public void onAccessibilityEvent(AccessibilityEvent e){} public void onInterrupt(){stop();} public void onDestroy(){stop();if(bar!=null)wm.removeView(bar);instance=null;super.onDestroy();}
 WindowManager.LayoutParams params(int w,int ht,int flags){return new WindowManager.LayoutParams(w,ht,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,flags,PixelFormat.TRANSLUCENT);}
 void configure(String n,int l,float s){stop();name=n;loops=Math.max(0,l);speed=Math.max(.5f,Math.min(5,s));try{steps=new JSONArray(getSharedPreferences("macros",0).getString(n,"[]"));}catch(Exception e){steps=new JSONArray();}if(bar!=null)wm.removeView(bar);bar=new LinearLayout(this);bar.setOrientation(1);bar.setBackgroundColor(0xee18243d);status=new TextView(this);status.setTextColor(-1);bar.addView(status);add("● Ghi",()->{stop();steps=new JSONArray();recording=true;last=SystemClock.uptimeMillis();capture();info("Đang ghi");});add("▶ Chạy",()->{stop();if(steps.length()==0){info("Chưa có thao tác");return;}running=true;index=round=0;next(++token);});add("Ⅱ Tạm / tiếp",()->{if(running){paused=!paused;if(!paused)next(++token);else{token++;info("Tạm dừng");}}});add("■ Dừng",()->{stop();info("Đã dừng");});add("× Đóng",()->{stop();wm.removeView(bar);bar=null;});WindowManager.LayoutParams p=params(-2,-2,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL);p.gravity=Gravity.TOP|Gravity.LEFT;p.y=120;wm.addView(bar,p);info(steps.length()+" bước");}
 void add(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(0xff45e8d0);bar.addView(b);b.setOnClickListener(v->r.run());}
 void info(String s){if(status!=null)status.setText(s);}
 void removeCapture(){if(overlay!=null){wm.removeView(overlay);overlay=null;}}
 void stop(){token++;h.removeCallbacksAndMessages(null);running=paused=recording=false;removeCapture();}
 void capture(){if(!recording||overlay!=null)return;overlay=new View(this);overlay.setBackgroundColor(0x01000000);overlay.setOnTouchListener((v,e)->{try{int a=e.getActionMasked();if(a==0){down=SystemClock.uptimeMillis();delay=Math.max(0,down-last);points=new JSONArray();}if(points==null)return true;if(a==0||a==1||a==2){points.put(new JSONArray().put(e.getRawX()).put(e.getRawY()));}if(a==1){JSONObject o=new JSONObject().put("p",points).put("d",Math.max(1,SystemClock.uptimeMillis()-down)).put("w",delay);steps.put(o);getSharedPreferences("macros",0).edit().putString(name,steps.toString()).apply();removeCapture();int t=token;send(o,1,()->{if(recording&&t==token){last=SystemClock.uptimeMillis();capture();info("Ghi: "+steps.length());}});}if(a==3)points=null;}catch(Exception ex){stop();info("Lỗi ghi");}return true;});wm.addView(overlay,params(-1,-1,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN));if(bar!=null){View b=bar;WindowManager.LayoutParams p=(WindowManager.LayoutParams)b.getLayoutParams();wm.removeView(b);wm.addView(b,p);}}
 void send(JSONObject o,float rate,Runnable done){try{JSONArray p=o.getJSONArray("p");Path path=new Path();for(int i=0;i<p.length();i++){JSONArray xy=p.getJSONArray(i);float x=(float)xy.getDouble(0),y=(float)xy.getDouble(1);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}long duration=Math.max(1,Math.min(60000,(long)(o.getLong("d")/rate)));boolean ok=dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,duration)).build(),new GestureResultCallback(){public void onCompleted(GestureDescription g){done.run();}public void onCancelled(GestureDescription g){stop();info("Thao tác bị hủy");}},h);if(!ok){stop();info("Không thể phát");}}catch(Exception e){stop();info("Lỗi thao tác");}}
 void next(int t){if(t!=token||!running||paused)return;if(index>=steps.length()){index=0;round++;if(loops>0&&round>=loops){stop();info("Hoàn thành "+round+" vòng");return;}}JSONObject o=steps.optJSONObject(index);info("Vòng "+(round+1)+" • "+(index+1)+"/"+steps.length());h.postDelayed(()->{if(t!=token||!running||paused)return;send(o,speed,()->{if(t==token){index++;next(t);}});},Math.max(20,(long)(o.optLong("w")/speed)));}
}